refentry.refsect1:
&reftitle.changelog;





    &Version;
    &Description;





    8.5.0

     Il passaggio di una stringa che non sia composta da un singolo byte è ora deprecato.

  &reftitle.examples;



    Esempio di ord


<?php
$str = "\n";
if (ord($str) == 10) {
    echo "Il primo carattere di \$str è un line feed.\n";
}
?>







    Esame dei singoli byte di una stringa UTF-8


<?php
$str = "🐘";
for ( $pos=0; $pos < strlen($str); $pos ++ ) {
 $byte = substr($str, $pos);
 echo 'Il byte ' . $pos . ' di $str ha valore ' . ord($byte) . PHP_EOL;
}
?>


    &example.outputs;

Il byte 0 di $str ha valore 240
Il byte 1 di $str ha valore 159
Il byte 2 di $str ha valore 144
Il byte 3 di $str ha valore 152
